scwin.cmb_BndClssCd_OnSelChange = function() {
    /** 채권분류 적용 */
    for (var i = 1; i <= dts_IsuList.getTotalRow(); i++) {
        dts_IsuList.setCellData(i, "AFCHG_BND_CLASS_CD", $c.stf.getObjectValue(cmb_BndClssCd));
    }
};
scwin.cmb_BndTpCd_OnSelChange = function() {
    /** 채권유형 적용 */
    for (var i = 1; i <= dts_IsuList.getTotalRow(); i++) {
        dts_IsuList.setCellData(i, "AFCHG_BND_TP_CD", $c.stf.getObjectValue(cmb_BndTpCd));
    }
};
scwin.cmb_IsuNm_OnSelChange = function() {
    /** 종목기준명 적용 */
    var vIdx = cmb_IsuNm.getSelectedIndex() + 1;
    for (var i = 1; i <= dts_IsuList.getTotalRow(); i++) {
        dts_IsuList.setCellData(i, "AFCHG_ISU_NM", dts_IsuSelList.getCellData(vIdx, "TEXT"));
        dts_IsuList.setCellData(i, "AFCHG_ISU_ABBRV", dts_IsuSelList.getCellData(vIdx, "TEXT2"));
        dts_IsuList.setCellData(i, "AFCHG_ISU_ENG_NM", dts_IsuSelList.getCellData(vIdx, "TEXT3"));
        dts_IsuList.setCellData(i, "AFCHG_ISU_ENG_ABBRV", dts_IsuSelList.getCellData(vIdx, "TEXT4"));
    }
};
scwin.dts_BndTpCd_OnLoadCompleted = function(rowcount) {
    //채권유형 공백란 추가
    dts_BndTpCd.insertRow(dts_BndTpCd.getRowPosition() - 1);
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
    }
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "처리완료"));
    }
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
    }
    scwin.fn_list_sync();
    scwin.vRegYn = 'N';
};
scwin.dts_IsuSelList_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        var vCmbRow = $c.cp.getNameValueRow(dts_IsuSelList, "TEXT", dts_IsuList.getCellData(1, "AFCHG_ISU_NM"));
        cmb_IsuNm.setSelectedIndex(vCmbRow - 1);
    }
};
